  transition:
    opacity 600ms var(--pulse-ease),
    transform 600ms var(--pulse-ease);
}

/* Per-row active value. --pulse-track is 0..1 across 4 tracks, so each row's
   active band is [i/4, (i+1)/4]. We map the smoothed track into a triangle
   peaking at the band center via calc(). */
.pulse-track[data-track-index="0"] {
  --pulse-track-active: clamp(0, 1, 1 - calc((var(--pulse-track) - 0.125) * 4));
}
.pulse-track[data-track-index="1"] {
  --pulse-track-active: clamp(0, 1, 1 - abs(calc(var(--pulse-track) - 0.375)) * 4);
}
.pulse-track[data-track-index="2"] {
  --pulse-track-active: clamp(0, 1, 1 - abs(calc(var(--pulse-track) - 0.625)) * 4);
}
.pulse-track[data-track-index="3"] {
  --pulse-track-active: clamp(0, 1, 1 - abs(calc(var(--pulse-track) - 0.875)) * 4);
}

.pulse-track__no {
  font-family: var(--font-grotesk), sans-serif;
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--pulse-dust-dim);
  /* Brightens to the track's accent as it becomes active. */
  opacity: calc(0.5 + 0.5 * var(--pulse-track-active));
}
.pulse-track[data-track-index="0"] .pulse-track__no { color: var(--pulse-particle-violet); }
.pulse-track[data-track-index="1"] .pulse-track__no { color: var(--pulse-ember); }
.pulse-track[data-track-index="2"] .pulse-track__no { color: var(--pulse-magenta); }
.pulse-track[data-track-index="3"] .pulse-track__no { color: var(--pulse-aqua); }

.pulse-track__body {
  min-width: 0;
}
.pulse-track__title {
  margin: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.3em 0.9em;
}
.pulse-track__title-en {
  font-family: var(--font-grotesk), sans-serif;
  font-size: clamp(1.1rem, 2.4vw, 1.6rem);
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--pulse-particle-hi);
}
.pulse-track__title-ko {
  font-size: clamp(0.9rem, 1.8vw, 1.1rem);
  color: var(--pulse-dust);
}
.pulse-track__blurb {
  margin: 0.3rem 0 0;
  font-size: 0.9rem;
  line-height: 1.45;
  color: var(--pulse-dust);
}
.pulse-track__blurb-ko {
  display: block;
  margin-top: 0.2rem;
  color: var(--pulse-dust-dim);
  font-size: 0.86rem;
}

.pulse-track__meta {
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.15rem;
  font-family: var(--font-grotesk), sans-serif;
}
.pulse-track__meta div {
  display: flex;
  align-items: baseline;
  gap: 0.4em;
}
.pulse-track__meta dt {
  font-size: 0.6rem;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--pulse-dust-dim);
}
.pulse-track__meta dd {
  margin: 0;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--pulse-dust);
}

/* Beat readout — the sequencer instrument voice */
.pulse-tracklist__readout {
  position: absolute;
  bottom: clamp(20px, 4vh, 36px);
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: baseline;
  gap: 0.4em;
  font-family: var(--font-grotesk), sans-serif;
  color: var(--pulse-dust-dim);
  pointer-events: none;
}
.pulse-tracklist__readout-bpm {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--pulse-magenta);
  letter-spacing: 0.02em;
}
.pulse-tracklist__readout-unit {
  font-size: 0.66rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}
.pulse-tracklist__readout-ko {
  font-weight: 400;
  letter-spacing: 0.1em;
  font-size: 0.66rem;
}

/* ==========================================================================
   03 · Footer — liner notes
   ========================================================================== */

.pulse-footer {
  max-width: 1020px;
  margin-inline: auto;
  padding: clamp(64px, 10vh, 120px) clamp(20px, 5vw, 64px) clamp(90px, 13vh, 150px);
  border-top: 1px solid var(--pulse-hairline);
  background: var(--pulse-void);
}
.pulse-footer__signoff {
  margin: 0 0 2.4rem;
  font-family: var(--font-grotesk), sans-serif;
  font-size: clamp(1.1rem, 2vw, 1.45rem);
  line-height: 1.5;
  color: var(--pulse-particle-hi);
}
.pulse-footer__ko {
  display: block;
  margin-top: 0.4rem;
  color: var(--pulse-dust);
}

.pulse-footer__credit {
  margin: 0 0 2.6rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 0.2rem 2rem;
}
.pulse-footer__credit div {
  display: flex;
  flex-wrap: wrap;
  gap: 0.2rem 1rem;
  padding: 0.6rem 0;
  border-bottom: 1px dotted var(--pulse-hairline);
}
.pulse-footer__credit dt {
  flex: 0 0 5.5rem;
  font-family: var(--font-grotesk), sans-serif;
  font-size: 0.66rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--pulse-dust-dim);
  line-height: 2;
}
.pulse-footer__credit dd {
  flex: 1 1 14rem;
  margin: 0;
  font-size: 0.9rem;
  color: var(--pulse-particle-hi);
}

.pulse-footer__note {
  margin: 0 0 2.4rem;
  padding: clamp(1.2rem, 2.5vw, 1.8rem);
  border: 1px solid var(--pulse-hairline);
  border-radius: 4px;
  background: linear-gradient(165deg, rgba(157, 78, 221, 0.06), rgba(157, 78, 221, 0) 60%), rgba(11, 13, 31, 0.5);
}
.pulse-footer__note-title {
  margin: 0 0 0.8rem;
  font-family: var(--font-grotesk), sans-serif;
  font-size: clamp(1.1rem, 2vw, 1.4rem);
  color: var(--pulse-particle-hi);
}
.pulse-footer__note p {
  margin: 0;
  font-size: 0.96rem;
  line-height: 1.6;
  color: var(--pulse-dust);
}
.pulse-footer__note-ko {
  display: block;
  margin-top: 0.6rem;
  color: var(--pulse-dust-dim);
}

.pulse-footer__nav {
  margin: 0 0 2.2rem;
  font-size: 0.9rem;
}
.pulse-footer__copy {
  margin: 0;
  font-family: var(--font-grotesk), sans-serif;
  font-size: 0.9rem;
  color: var(--pulse-dust);
}
.pulse-footer__copy .pulse-footer__ko {
  display: inline;
  margin: 0 0 0 0.4em;
}

/* ==========================================================================
   Scroll reveals — JS-gated pre-state, transform/opacity only
   ========================================================================== */

.pulse-js [data-reveal] {
  opacity: 0;
  transform: translateY(20px);
  transition:
    opacity 700ms var(--pulse-ease),
    transform 700ms var(--pulse-ease);
  will-change: opacity, transform;
}
.pulse-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* ==========================================================================
   Reduced motion — the nebula is a composed still; everything readable
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  /* Reveals simply visible */
  .pulse-js [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }

  /* The wordmark holds still (no breathe) */
  .pulse-js [data-pulse-breathe] {
    letter-spacing: -0.02em;
  }

  /* Track rows hold still (no translateY), but keep emphasis opacity so the
     scroll-scrubbed palette still reads. */
  .pulse-track {
    transform: none;
  }

  /* Hold the beat at the composed mid-value so the void/core read as
     "the field, mid-breath" rather than flat. */
  #pulse-top {
    --pulse-beat: 0.35;
  }
}
